/**
 * Bounded in-memory log buffer for the playground Logs tab.
 *
 * Wraps {@link ServeOptions.logger} so every channel/session line that hits
 * the console is also retained for `GET /v1/logs`.
 */
export function createLogRing(options = {}) {
    const capacity = Math.max(1, options.capacity ?? 1000);
    const entries = [];
    let nextIndex = 0;
    function push(line) {
        entries.push({
            index: nextIndex,
            at: new Date().toISOString(),
            line,
        });
        nextIndex += 1;
        while (entries.length > capacity) {
            entries.shift();
        }
    }
    return {
        push,
        since(after = -1) {
            if (entries.length === 0) {
                return [];
            }
            const start = entries.findIndex((e) => e.index > after);
            if (start < 0) {
                return [];
            }
            return entries.slice(start);
        },
        wrap(inner) {
            return (line) => {
                push(line);
                inner(line);
            };
        },
    };
}
